INSERT OR REPLACE INTO variants (id, name, product_id, images, images_alt, price, applicable_gst, technical_details) VALUES ('ko-bc-jpro-sp', 'KO-1350 JUGLE PRO (Side Pack)', 'ko-bc-jpro', '["/products/brushcutter.webp"]', '["KOREVA KO-1350 JUNGLE PRO Side Pack Brush Cutter"]', '15000.00', '5', '{"Brand":"Koreva","Model":"KO-1350 JUGLE PRO","Engine Type":"Single Cylinder, Four Stroke, Air Cooled","Engine Model":"JX35","Displacement":"35.8 CC","Engine Power":"1.35 HP (1.0 Kw)","Carburator":"Diafragm-type","Fuel Tank Capacity":"630 ml","Engine Oil Capacity":"80 ml","Carry Type":"Side Pack","Shaft Type":"Aluminium Tube","Shaft Pipe Diameter":"28 mm","Shaft Pipe Thickness":"2 mm","Shaft Teeth":"9 teeth","Drive System":"Direct Shaft Drive","Machinery Type":"Brush Cutter & Weed Trimmer","Machine Weight":"8.5 Kg"}');
